# Cache ttl and eviction policy.

DEFAULT_TTL_SECONDS = 300
MAX_ENTRIES = 512


class TtlCachePolicy:
    """Least-recently-used eviction with a bounded ttl."""

    def __init__(self, ttl_seconds: int = DEFAULT_TTL_SECONDS) -> None:
        self.ttl_seconds = ttl_seconds
        self.entries: dict[str, int] = {}

    def store(self, key: str, inserted_at: int) -> None:
        """Insert an entry and evict the oldest entry when the bound is exceeded."""
        self.entries[key] = inserted_at
        if len(self.entries) > MAX_ENTRIES:
            oldest = min(self.entries, key=self.entries.get)  # type: ignore[arg-type]
            del self.entries[oldest]

    def is_fresh(self, key: str, now: int) -> bool:
        """Report whether an entry is still within its ttl window."""
        inserted_at = self.entries.get(key)
        if inserted_at is None:
            return False
        return now - inserted_at <= self.ttl_seconds

# Hybrid rank fusion.

RECIPROCAL_RANK_CONSTANT = 60


def reciprocal_rank_fusion(rankings: list[list[str]]) -> dict[str, float]:
    """Fuse lexical and semantic rankings with reciprocal rank fusion."""
    fused: dict[str, float] = {}
    for ranking in rankings:
        for rank, identifier in enumerate(ranking, start=1):
            fused[identifier] = fused.get(identifier, 0.0) + (
                1.0 / (RECIPROCAL_RANK_CONSTANT + rank)
            )
    return fused


def best_rank(identifier: str, ranking: list[str]) -> int | None:
    """Return the one-based rank of an identifier in a ranking."""
    for rank, candidate in enumerate(ranking, start=1):
        if candidate == identifier:
            return rank
    return None

