def module_{index}_load(store: dict[str, str]) -> str:
    """Load module {index} state from the store."""
    return store.get("module-{index}", "")


def module_{index}_store(store: dict[str, str], value: str) -> None:
    """Store module {index} state."""
    store["module-{index}"] = value


def module_{index}_summary() -> str:
    """Summarize module {index} ownership."""
